create table public.kakao_multi_batches (id uuid,owner_id uuid,day date,generation bigint,delivery_deadline timestamp with time zone,status text,outcome text,created_at timestamp with time zone,completed_at timestamp with time zone,scope_hash text);
create table public.kakao_multi_connections (owner_id uuid,account_id text,encrypted_tokens text,confirmation_hash text,confirmation_expires_at timestamp with time zone,status text,generation bigint,talk_message_granted boolean,updated_at timestamp with time zone);
create table public.kakao_multi_controls (singleton boolean,enabled boolean,monthly_message_budget integer,monthly_function_budget integer,cost_verified_until timestamp with time zone,updated_at timestamp with time zone,tick_endpoint text);
create table public.kakao_multi_jobs (id uuid,batch_id uuid,owner_id uuid,generation bigint,part integer,body text,status text,outcome text,claimed_at timestamp with time zone,completed_at timestamp with time zone,claim_token uuid);
create table public.kakao_multi_preferences (owner_id uuid,delivery_time time without time zone,days integer[],enabled boolean,send_empty boolean,admin_paused boolean,updated_at timestamp with time zone,weather_region_key text);
create table public.kakao_multi_runs (id uuid,entered_at timestamp with time zone,claimed_job uuid,run_kind text);
create table public.kakao_weather_regions (region_key text,label text,nx integer,ny integer,enabled boolean,verified_at timestamp with time zone,forecast_code text);
create table public.organization_units (id uuid,code text,name text,unit_type text,parent_id uuid,sort_order integer,is_active boolean,created_at timestamp with time zone,updated_at timestamp with time zone);
create table public.profiles (id uuid,login_id text,auth_email text,display_name text,role text,is_active boolean,organization_unit_id uuid,position_code text,created_at timestamp with time zone,updated_at timestamp with time zone,last_login_at timestamp with time zone);
create table public.sales_empty_days (owner uuid,day date);
create table public.sales_events (id uuid,owner uuid,unit uuid,day date,start_time time without time zone,end_time time without time zone,kind text,title text,place text,note text,common boolean,status text,result text,help text,revision integer,companion uuid,time_pending boolean,previous_event uuid,created_at timestamp with time zone,contact_method text,case_id uuid,deleted_at timestamp with time zone,deletion_batch uuid,series_id uuid,help_recipient uuid);

create table public.kakao_multi_welcomes(owner_id uuid,id uuid,status text,first_confirmed_at timestamptz,ready_at timestamptz,day date,regular_not_before date,generation bigint,batch_id uuid,ticket_hash text,ticket_expires_at timestamptz,expires_at timestamptz,claim_token uuid,scope_hash text,completed_at timestamptz);
